SELECT fn_cp_import_case('mineurs-enfant-perdu-centre-commercial', '{"slug": "mineurs-enfant-perdu-centre-commercial", "title": "Il a quatre ans et ne sait pas dire son nom de famille", "theme_slug": "mineurs", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 16 heures. Un agent de sécurité d''un centre commercial vous amène un petit garçon d''environ 4 ans, trouvé seul et en pleurs près d''une fontaine, incapable de retrouver ses parents. L''enfant sait dire son prénom, Léo, mais ne connaît ni son nom de famille ni son adresse, et reste incapable de décrire précisément à quoi ressemble le parent qu''il cherche au-delà de « maman ».\n\nAucune annonce n''a encore été diffusée dans le centre commercial pour signaler cette découverte. L''enfant se calme progressivement à votre contact mais reste anxieux, s''accrochant à votre main dès que vous tentez de vous éloigner, même de quelques pas.\n\nQuelques minutes plus tard, une femme se présente en affirmant être sa mère, mais l''enfant, en la voyant, ne réagit pas avec le soulagement immédiat que vous attendriez, restant un instant hésitant avant de se diriger vers elle.", "questions": [{"position": 1, "max_points": 5, "label": "Comment organisez-vous les recherches pour retrouver les parents de cet enfant très jeune et peu communicant ?", "hint": "L''absence d''information verbale exploitable impose de mobiliser d''autres moyens que le seul témoignage de l''enfant.", "perfect": "Je fais diffuser sans délai une annonce dans le centre commercial décrivant l''enfant, son prénom et le lieu où il a été retrouvé, cette diffusion étant le moyen le plus rapide de toucher des parents affolés qui le cherchent probablement activement.\n\nJe ne presse pas l''enfant de questions qu''il ne peut pas comprendre ou auxquelles il ne peut pas répondre compte tenu de son jeune âge, en adaptant mes questions à ce qu''un enfant de 4 ans peut raisonnablement savoir, comme son prénom ou des détails simples sur sa journée.\n\nJe sollicite les caméras de vidéoprotection du centre commercial pour tenter de retracer son parcours et d''identifier le moment où il s''est retrouvé seul, ce qui pourrait aider à localiser la zone où ses parents le cherchent.\n\nJe reste avec lui de manière rassurante en attendant, en gardant à l''esprit que son anxiété et son besoin de contact physique sont des réactions normales pour un enfant de cet âge séparé de ses parents dans un lieu inconnu.", "points": [{"position": 1, "label": "Faire diffuser sans délai une annonce dans le centre commercial", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Moyen le plus rapide de toucher des parents qui cherchent activement.", "groups": [{"position": 1, "keywords": ["diffuser une annonce", "sans délai", "parents cherchent activement"]}]}, {"position": 2, "label": "Adapter les questions à ce qu''un enfant de 4 ans peut savoir", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas presser avec des questions incompréhensibles pour son âge.", "groups": [{"position": 1, "keywords": ["adapter les questions", "âge de l''enfant", "pas de pression"]}]}, {"position": 3, "label": "Solliciter les caméras de vidéoprotection pour retracer son parcours", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Identifier le moment et la zone où il s''est retrouvé seul.", "groups": [{"position": 1, "keywords": ["vidéoprotection", "retracer le parcours", "localiser la zone"]}]}, {"position": 4, "label": "Rester rassurante en attendant, comprenant son besoin de contact", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactions normales pour un enfant séparé de ses parents.", "groups": [{"position": 1, "keywords": ["rester rassurante", "besoin de contact", "réaction normale"]}]}]}, {"position": 2, "max_points": 5, "label": "Face à cette femme qui se présente comme sa mère, alors que l''enfant hésite un instant avant de la rejoindre, comment procédez-vous avant toute remise ?", "hint": "Une hésitation, même brève, mérite d''être prise au sérieux avant de considérer la remise comme acquise.", "perfect": "Je ne remets pas immédiatement l''enfant sur la seule affirmation de cette femme, cette hésitation initiale de l''enfant, même brève, méritant d''être prise en compte avant de considérer le lien comme établi avec certitude.\n\nJe lui demande de présenter un document permettant de vérifier son identité et, si possible, un lien avec l''enfant, comme une pièce d''identité mentionnant son nom de famille que je pourrais rapprocher de ce que l''enfant a pu me dire.\n\nJe pose des questions simples à l''enfant en présence de cette femme, comme lui demander s''il la reconnaît et comment il l''appelle, son langage corporel et sa réaction pouvant m''éclairer sur la réalité du lien affirmé.\n\nJe reste attentive au fait que cette hésitation initiale peut aussi simplement traduire le trouble et la fatigue d''un enfant de 4 ans après ces minutes d''angoisse, sans que cela signifie nécessairement une absence de lien réel, ce qui m''incite à une vérification mesurée plutôt qu''à une suspicion disproportionnée.", "points": [{"position": 1, "label": "Ne pas remettre immédiatement sur la seule affirmation de la femme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérifier le lien avant toute remise.", "groups": [{"position": 1, "keywords": ["ne pas remettre immédiatement", "hésitation prise en compte", "vérifier avant"]}]}, {"position": 2, "label": "Demander un document permettant de vérifier l''identité et le lien", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pièce d''identité à rapprocher de ce que l''enfant a pu dire.", "groups": [{"position": 1, "keywords": ["document d''identité", "vérifier le lien", "rapprocher les informations"]}]}, {"position": 3, "label": "Poser des questions simples à l''enfant en sa présence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Observer le langage corporel et la réaction de l''enfant.", "groups": [{"position": 1, "keywords": ["questions simples", "langage corporel", "réaction observée"]}]}, {"position": 4, "label": "Considérer que l''hésitation peut traduire simplement le trouble de l''enfant", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vérification mesurée plutôt que suspicion disproportionnée.", "groups": [{"position": 1, "keywords": ["trouble de l''enfant", "vérification mesurée", "sans suspicion disproportionnée"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois le lien confirmé et l''enfant remis à sa mère visiblement soulagée, comment concluez-vous cette intervention ?", "hint": "Un dénouement heureux ne dispense pas d''un minimum de rigueur et d''accompagnement avant de considérer l''affaire close.", "perfect": "Je m''assure que la mère comprend bien les circonstances de cette séparation, ce qui peut l''aider à mieux surveiller son enfant à l''avenir dans ce type d''environnement fréquenté.\n\nJe recueille brièvement son propre récit de ce qui s''est passé de son point de vue, ce qui peut compléter utilement ma compréhension de l''incident sans pour autant en faire une procédure disproportionnée pour un enfant perdu quelques minutes.\n\nJe reste attentive à l''état émotionnel de la mère elle-même, qui a probablement vécu des minutes d''angoisse intense, en lui offrant un moment de réconfort avant qu''elle ne reparte avec son enfant.\n\nJe consigne cette intervention de manière proportionnée à sa gravité réelle, sans excès de formalisme pour un incident qui s''est finalement résolu favorablement et rapidement.", "points": [{"position": 1, "label": "S''assurer que la mère comprend les circonstances pour l''avenir", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Aide à mieux surveiller l''enfant dans ce type d''environnement.", "groups": [{"position": 1, "keywords": ["comprendre les circonstances", "surveillance future", "environnement fréquenté"]}]}, {"position": 2, "label": "Recueillir brièvement son récit sans procédure disproportionnée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Compléter la compréhension sans excès pour un incident bref.", "groups": [{"position": 1, "keywords": ["récit bref", "sans disproportion", "incident résolu"]}]}, {"position": 3, "label": "Rester attentive à l''état émotionnel de la mère", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Minutes d''angoisse intense méritant un moment de réconfort.", "groups": [{"position": 1, "keywords": ["état émotionnel de la mère", "réconfort", "angoisse vécue"]}]}, {"position": 4, "label": "Consigner de manière proportionnée à la gravité réelle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sans excès de formalisme pour un incident résolu favorablement.", "groups": [{"position": 1, "keywords": ["consigner proportionnellement", "sans excès de formalisme", "résolu favorablement"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('mineurs-harcelement-scolaire-signale-parents', '{"slug": "mineurs-harcelement-scolaire-signale-parents", "title": "Les parents veulent des noms et menacent d''agir eux-mêmes", "theme_slug": "mineurs", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 17 h 30. M. et Mme ARNAUD se présentent au commissariat, très en colère, pour signaler que leur fille de 13 ans est harcelée depuis plusieurs mois par un groupe d''élèves de sa classe, ce qu''ils viennent de découvrir en consultant son téléphone. Ils exigent d''obtenir immédiatement les noms complets des harceleurs présumés et déclarent, sur un ton menaçant, qu''ils « iront leur parler directement » si rien n''est fait rapidement par les autorités.\n\nLeur fille n''est pas présente lors de cet échange, restée à la maison, et vous ne disposez à ce stade que du récit des parents, eux-mêmes très affectés émotionnellement par cette découverte et par le sentiment d''avoir laissé perdurer une situation dont ils ignoraient tout jusqu''à aujourd''hui.\n\nM. ARNAUD, en particulier, semble sur le point de partir sur-le-champ pour se rendre au domicile de l''un des élèves qu''il a identifié grâce aux messages consultés sur le téléphone de sa fille.", "questions": [{"position": 1, "max_points": 5, "label": "Comment désamorcez-vous l''intention de M. ARNAUD de se faire justice lui-même auprès de la famille d''un des élèves identifiés ?", "hint": "Sa colère est légitime, mais le risque de passage à l''acte de sa part doit être traité comme une priorité immédiate.", "perfect": "Je reconnais explicitement la légitimité de sa colère face à ce qu''il vient de découvrir, sans la minimiser, tout en étant ferme sur le fait qu''une confrontation directe de sa part ne ferait qu''aggraver la situation et l''exposerait lui-même à des conséquences pénales.\n\nJe lui explique clairement que cette démarche personnelle risquerait de compromettre le traitement approprié de la situation par les canaux adaptés, notamment l''établissement scolaire et les services compétents, plutôt que de la résoudre.\n\nJe reste attentive à son état émotionnel, qui traduit avant tout une détresse de parent découvrant la souffrance de son enfant, en cherchant à canaliser cette énergie vers des démarches constructives plutôt que vers une confrontation risquée.\n\nJe lui propose des actions concrètes qu''il peut engager immédiatement à ma place de sa propre initiative, ce qui peut apaiser son sentiment d''impuissance sans qu''il ait besoin de se rendre lui-même chez la famille identifiée.", "points": [{"position": 1, "label": "Reconnaître la légitimité de sa colère tout en étant ferme sur les risques", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : désamorcer l''intention parentale de se faire justice.", "groups": [{"position": 1, "keywords": ["reconnaître la colère", "ferme sur les risques", "désamorcer"]}]}, {"position": 2, "label": "Expliquer que la confrontation directe compromettrait le traitement approprié", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Canaux adaptés plutôt qu''une démarche personnelle risquée.", "groups": [{"position": 1, "keywords": ["compromettre le traitement", "canaux adaptés", "démarche personnelle risquée"]}]}, {"position": 3, "label": "Reconnaître que sa détresse de parent nécessite d''être canalisée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vers des démarches constructives plutôt qu''une confrontation.", "groups": [{"position": 1, "keywords": ["détresse de parent", "canaliser l''énergie", "démarches constructives"]}]}, {"position": 4, "label": "Proposer des actions concrètes immédiates pour apaiser son impuissance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sans qu''il ait besoin de se rendre lui-même chez la famille.", "groups": [{"position": 1, "keywords": ["actions concrètes", "apaiser l''impuissance", "sans se rendre lui-même"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous leur demande d''obtenir immédiatement les noms complets des élèves harceleurs présumés ?", "hint": "Cette demande légitime en apparence doit être appréciée au regard des risques qu''elle ferait courir si elle était satisfaite dans l''instant.", "perfect": "Je ne leur communique pas immédiatement les noms complets qu''ils réclament, cette information, une fois entre leurs mains dans cet état de colère, pouvant précisément alimenter le risque de passage à l''acte que je cherche à désamorcer.\n\nJe leur explique que l''identification précise des auteurs et la qualification des faits relèvent d''une enquête qui doit être menée avec méthode, plutôt que d''une communication immédiate d''informations encore non vérifiées de mon côté.\n\nJe recueille avec eux les éléments dont ils disposent, notamment les messages consultés sur le téléphone de leur fille, ce qui alimentera utilement le dossier sans pour autant leur remettre une liste de noms à ce stade.\n\nJe leur explique que cette prudence sur la communication des noms n''est pas un manque de considération pour leur demande légitime, mais une nécessité pour que la suite de la procédure se déroule dans un cadre qui protège tout le monde, y compris leur propre fille.", "points": [{"position": 1, "label": "Ne pas communiquer immédiatement les noms complets réclamés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter d''alimenter le risque de passage à l''acte dans cet état de colère.", "groups": [{"position": 1, "keywords": ["ne pas communiquer les noms", "risque de passage à l''acte", "état de colère"]}]}, {"position": 2, "label": "Expliquer que l''identification relève d''une enquête méthodique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Plutôt qu''une communication immédiate d''informations non vérifiées.", "groups": [{"position": 1, "keywords": ["enquête méthodique", "informations non vérifiées", "pas immédiat"]}]}, {"position": 3, "label": "Recueillir les éléments dont ils disposent pour alimenter le dossier", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Messages consultés utiles sans remettre une liste de noms.", "groups": [{"position": 1, "keywords": ["recueillir les éléments", "messages consultés", "sans liste de noms"]}]}, {"position": 4, "label": "Expliquer que cette prudence protège tout le monde y compris leur fille", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Pas un manque de considération pour leur demande légitime.", "groups": [{"position": 1, "keywords": ["protège tout le monde", "pas un manque de considération", "leur fille aussi"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite pour que leur fille, absente de cet échange, soit correctement prise en charge ?", "hint": "L''absence de la victime directe lors de ce signalement initial ne doit pas retarder sa propre prise en charge.", "perfect": "Je leur explique l''importance de recueillir également le récit de leur fille elle-même, dans un cadre adapté et bienveillant, plutôt que de se contenter uniquement de leur propre lecture des messages consultés.\n\nJe les oriente vers une prise de contact avec l''établissement scolaire, qui doit être informé de cette situation pour pouvoir agir de son côté sur le harcèlement en cours, cette démarche complétant utilement le signalement policier.\n\nJe recommande qu''un accompagnement psychologique soit envisagé pour leur fille, le harcèlement prolongé qu''elle a subi pouvant avoir des conséquences qui dépassent la seule résolution de l''aspect procédural de cette affaire.\n\nJe reste attentive à ce que la suite de cette procédure implique leur fille de manière adaptée à son âge, sans qu''elle ne se sente elle-même mise en cause ou exposée par la colère de ses parents.", "points": [{"position": 1, "label": "Souligner l''importance de recueillir le récit de la fille elle-même", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Dans un cadre adapté plutôt que la seule lecture des messages par les parents.", "groups": [{"position": 1, "keywords": ["récit de la fille", "cadre adapté", "pas seulement la lecture parentale"]}]}, {"position": 2, "label": "Orienter vers une prise de contact avec l''établissement scolaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Complément utile au signalement policier.", "groups": [{"position": 1, "keywords": ["établissement scolaire", "compléter le signalement", "agir de son côté"]}]}, {"position": 3, "label": "Recommander un accompagnement psychologique pour la fille", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Conséquences du harcèlement dépassant l''aspect procédural.", "groups": [{"position": 1, "keywords": ["accompagnement psychologique", "conséquences du harcèlement", "au-delà du procédural"]}]}, {"position": 4, "label": "S''assurer qu''elle ne se sente pas mise en cause par la colère parentale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Implication adaptée à son âge sans exposition supplémentaire.", "groups": [{"position": 1, "keywords": ["pas mise en cause", "adapté à son âge", "sans exposition"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('mineurs-diffusion-images-intimes-entre-eleves', '{"slug": "mineurs-diffusion-images-intimes-entre-eleves", "title": "La photo a circulé dans trois classes en une matinée", "theme_slug": "mineurs", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 11 heures. Vous êtes appelés dans un collège suite à la découverte, par un enseignant, de la diffusion massive d''une photographie intime d''une élève de 14 ans, initialement envoyée à son petit ami dans un cadre privé, mais désormais partagée dans les groupes de discussion d''au moins trois classes différentes en l''espace d''une seule matinée. La diffusion semble se poursuivre activement au moment où vous intervenez.\n\nLa victime, effondrée, est prise en charge par l''infirmière scolaire. Plusieurs élèves, potentiellement une dizaine à ce stade, ont participé au partage de cette image, certains par simple retransmission sans réflexion, d''autres avec des commentaires dégradants ajoutés. Le petit ami initial, également mineur, nie être à l''origine de la première diffusion, sans que cela ne puisse être vérifié dans l''immédiat.\n\nL''urgence de la situation tient autant à la détresse de la victime qu''à la propagation continue de l''image, qui touche de nouveaux élèves à chaque minute qui passe.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité absolue face à cette diffusion qui se poursuit activement au moment de votre intervention ?", "hint": "Faire cesser la propagation en cours a un caractère d''urgence qui dépasse même l''identification complète des responsables.", "perfect": "Ma priorité absolue est de faire cesser la diffusion en cours, chaque minute supplémentaire aggravant l''exposition de la victime et élargissant le cercle des personnes ayant vu ou partagé cette image intime.\n\nJe demande à la direction de l''établissement de communiquer sans délai à l''ensemble des classes concernées une consigne claire de cessation immédiate du partage et de suppression de l''image, cette communication institutionnelle pouvant avoir un effet plus rapide qu''une enquête individuelle menée élève par élève.\n\nJe recueille auprès de l''enseignant et de la direction les éléments déjà connus sur l''ampleur de la diffusion, ce qui m''aide à évaluer combien d''appareils et de personnes sont potentiellement concernés à cet instant précis.\n\nJe ne me focalise pas exclusivement sur la recherche de l''auteur initial de la diffusion avant d''avoir engagé cette action d''urgence sur l''arrêt de la propagation, cette dernière étant prioritaire sur l''identification complète des responsabilités.", "points": [{"position": 1, "label": "Prioriser l''arrêt de la diffusion en cours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : faire cesser la diffusion avant l''identification complète.", "groups": [{"position": 1, "keywords": ["arrêt de la diffusion", "priorité absolue", "chaque minute compte"]}]}, {"position": 2, "label": "Demander à la direction une communication immédiate de cessation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Communication institutionnelle plus rapide qu''une enquête individuelle.", "groups": [{"position": 1, "keywords": ["communication de la direction", "cessation immédiate", "plus rapide"]}]}, {"position": 3, "label": "Recueillir les éléments connus sur l''ampleur de la diffusion", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Évaluer combien de personnes sont concernées à cet instant.", "groups": [{"position": 1, "keywords": ["ampleur de la diffusion", "évaluer l''étendue", "à cet instant"]}]}, {"position": 4, "label": "Ne pas se focaliser exclusivement sur l''auteur initial avant l''urgence", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "L''arrêt de la propagation prime sur l''identification complète.", "groups": [{"position": 1, "keywords": ["pas exclusivement sur l''auteur", "prime sur l''identification", "urgence d''abord"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous la dizaine de mineurs ayant participé au partage, dont les degrés d''implication varient fortement ?", "hint": "Traiter tous les participants de manière uniforme méconnaîtrait la réalité de leurs rôles très différents dans cette diffusion.", "perfect": "Je distingue clairement les différents degrés d''implication, entre ceux qui ont simplement retransmis l''image sans réflexion et ceux qui ont ajouté des commentaires dégradants, ces deux comportements ne relevant pas de la même gravité.\n\nJe traite chacun de ces mineurs avec discernement, en évitant une réponse uniforme qui traiterait de la même manière un geste irréfléchi de retransmission et un comportement délibérément humiliant envers la victime.\n\nJe respecte le cadre protecteur applicable à chacun de ces mineurs dans le recueil de leurs explications, notamment concernant la présence de leurs représentants légaux pour toute audition formelle qui serait nécessaire.\n\nJe ne perds pas de vue que l''objectif éducatif et de prise de conscience reste central pour la majorité de ces mineurs, sans pour autant minimiser la gravité de l''atteinte qu''ils ont collectivement causée à la victime.", "points": [{"position": 1, "label": "Distinguer les différents degrés d''implication dans le partage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : traiter les mineurs auteurs avec discernement.", "groups": [{"position": 1, "keywords": ["distinguer les degrés", "retransmission vs commentaires", "gravité différente"]}]}, {"position": 2, "label": "Éviter une réponse uniforme entre geste irréfléchi et comportement délibéré", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas traiter de la même manière des comportements de gravité différente.", "groups": [{"position": 1, "keywords": ["pas de réponse uniforme", "geste irréfléchi", "comportement délibéré"]}]}, {"position": 3, "label": "Respecter le cadre protecteur applicable à chaque mineur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Représentants légaux présents pour toute audition formelle.", "groups": [{"position": 1, "keywords": ["cadre protecteur", "représentants légaux", "audition formelle"]}]}, {"position": 4, "label": "Garder l''objectif éducatif central sans minimiser la gravité collective", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prise de conscience pour la majorité sans minimiser l''atteinte causée.", "groups": [{"position": 1, "keywords": ["objectif éducatif", "sans minimiser", "atteinte collective"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la prise en charge de la victime, effondrée et confrontée à une exposition qui continue de s''étendre ?", "hint": "La détresse de la victime nécessite une attention immédiate distincte du travail d''enquête sur les auteurs.", "perfect": "Je m''assure que la victime bénéficie d''une prise en charge psychologique immédiate, en coordination avec l''infirmière scolaire déjà présente à ses côtés, cette détresse nécessitant une attention aussi urgente que l''arrêt de la diffusion elle-même.\n\nJe recueille son récit avec une délicatesse particulière, en évitant de la faire revivre inutilement les détails les plus douloureux de cette exposition, tout en obtenant les éléments nécessaires pour la suite de la procédure.\n\nJe l''informe, avec des mots adaptés à son âge, des démarches qui vont être engagées pour faire cesser la diffusion et traiter la situation des autres élèves impliqués, ce qui peut lui donner un sentiment de prise en charge effective de sa situation.\n\nJe reste attentive à ce que sa famille soit informée et associée à cette prise en charge, sans que cette information ne soit gérée dans la précipitation qui pourrait ajouter à sa détresse actuelle.", "points": [{"position": 1, "label": "S''assurer d''une prise en charge psychologique immédiate", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Attention aussi urgente que l''arrêt de la diffusion.", "groups": [{"position": 1, "keywords": ["prise en charge psychologique", "immédiate", "aussi urgente"]}]}, {"position": 2, "label": "Recueillir son récit avec délicatesse sans la faire revivre inutilement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Obtenir les éléments nécessaires sans détails douloureux superflus.", "groups": [{"position": 1, "keywords": ["délicatesse", "sans revivre inutilement", "éléments nécessaires"]}]}, {"position": 3, "label": "L''informer avec des mots adaptés des démarches engagées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sentiment de prise en charge effective de sa situation.", "groups": [{"position": 1, "keywords": ["informer avec des mots adaptés", "démarches engagées", "prise en charge effective"]}]}, {"position": 4, "label": "S''assurer que sa famille soit informée sans précipitation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter d''ajouter à la détresse actuelle par une gestion précipitée.", "groups": [{"position": 1, "keywords": ["famille informée", "sans précipitation", "ne pas ajouter à la détresse"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('mineurs-racket-abords-etablissement', '{"slug": "mineurs-racket-abords-etablissement", "title": "Il dit avoir prêté son téléphone, ses mains tremblent", "theme_slug": "mineurs", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 h 45. Un enseignant, inquiet, vous signale un élève de 12 ans, Nathan, qu''il a surpris en larmes aux abords du collège après les cours, expliquant de manière hésitante avoir « prêté » son téléphone à des élèves plus âgés qui l''auraient ensuite gardé. Nathan, interrogé, minimise fortement la situation, insistant sur le fait que c''était « son choix » de le prêter, mais ses mains tremblent visiblement pendant qu''il vous parle.\n\nIl refuse dans un premier temps de donner des détails supplémentaires, jetant des regards inquiets vers la sortie du collège comme s''il craignait d''être vu en train de parler avec vous. Il finit par évoquer, à voix très basse, que « ça arrive souvent » sans vouloir préciser davantage ce que ce « souvent » recouvre exactement.\n\nCes mêmes élèves plus âgés, selon les informations de l''enseignant, fréquentent quotidiennement les mêmes abords du collège que Nathan, ce qui signifie qu''il devra vraisemblablement les recroiser dès le lendemain matin.", "questions": [{"position": 1, "max_points": 5, "label": "Comment interprétez-vous la version d''un « prêt volontaire » donnée par Nathan malgré son état de tremblement visible ?", "hint": "Le décalage entre le discours minimisant et l''état physique de l''enfant est lui-même une information précieuse.", "perfect": "Je ne prends pas cette version d''un prêt volontaire pour argent comptant, le tremblement visible de Nathan et son regard inquiet vers la sortie traduisant une peur incompatible avec l''idée d''un geste réellement libre et sans pression.\n\nJe reconnais que cette minimisation est un comportement fréquent chez une jeune victime de racket, qui peut avoir honte de la situation ou craindre des représailles si elle admettait la réalité de la contrainte exercée sur elle.\n\nJe ne le confronte pas frontalement en lui disant qu''il ment, ce qui risquerait de le braquer davantage, mais je reste attentive aux signes physiques qui contredisent son discours verbal pour orienter la suite de mon approche.\n\nJe prends au sérieux sa mention selon laquelle « ça arrive souvent », cette phrase lâchée à voix basse pouvant révéler un système de racket répété plutôt qu''un incident isolé qu''il chercherait à me faire croire.", "points": [{"position": 1, "label": "Ne pas prendre la version du prêt volontaire pour argent comptant", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Le tremblement traduit une peur incompatible avec un geste libre.", "groups": [{"position": 1, "keywords": ["pas pour argent comptant", "tremblement", "peur incompatible"]}]}, {"position": 2, "label": "Reconnaître que la minimisation est fréquente chez une jeune victime de racket", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Honte ou crainte de représailles expliquant ce comportement.", "groups": [{"position": 1, "keywords": ["minimisation fréquente", "honte", "crainte de représailles"]}]}, {"position": 3, "label": "Ne pas le confronter frontalement en lui disant qu''il ment", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rester attentif aux signes physiques contredisant le discours.", "groups": [{"position": 1, "keywords": ["ne pas confronter frontalement", "signes physiques", "orienter l''approche"]}]}, {"position": 4, "label": "Prendre au sérieux sa mention que « ça arrive souvent »", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Possible système de racket répété plutôt qu''incident isolé.", "groups": [{"position": 1, "keywords": ["ça arrive souvent", "système répété", "pas isolé"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment abordez-vous la question de son retour au collège dès le lendemain matin, sachant qu''il recroisera probablement les mêmes élèves ?", "hint": "La contrainte de proximité quotidienne change radicalement la nature du danger par rapport à une agression ponctuelle.", "perfect": "Je prends explicitement en compte cette contrainte de proximité quotidienne, Nathan devant recroiser ces mêmes élèves dès le lendemain, ce qui distingue sa situation d''une agression isolée sans suite prévisible.\n\nJe considère que ma priorité n''est pas seulement de traiter l''incident de ce jour, mais d''organiser une protection qui tienne compte de cette récurrence probable et de la peur légitime que Nathan éprouve à l''idée de ce retour.\n\nJe coordonne avec l''établissement scolaire les mesures qui pourraient être mises en place pour sécuriser sa présence dans l''établissement, comme une vigilance accrue du personnel aux abords ou une organisation différente de ses trajets.\n\nJe reste attentive à ne pas le rassurer par une promesse vague de protection que je ne pourrais pas concrètement garantir, en privilégiant des mesures pratiques et vérifiables plutôt qu''un discours rassurant mais creux.", "points": [{"position": 1, "label": "Prendre en compte la contrainte de proximité quotidienne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sécuriser la victime dans la durée, pas seulement le jour même.", "groups": [{"position": 1, "keywords": ["contrainte de proximité", "recroiser demain", "distinct d''une agression isolée"]}]}, {"position": 2, "label": "Organiser une protection tenant compte de la récurrence probable", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Priorité au-delà du seul traitement de l''incident du jour.", "groups": [{"position": 1, "keywords": ["protection dans la durée", "récurrence probable", "au-delà de l''incident"]}]}, {"position": 3, "label": "Coordonner avec l''établissement des mesures de sécurisation concrètes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance accrue ou organisation différente des trajets.", "groups": [{"position": 1, "keywords": ["coordonner avec l''établissement", "vigilance accrue", "trajets différents"]}]}, {"position": 4, "label": "Ne pas le rassurer par une promesse vague non garantie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Privilégier des mesures pratiques et vérifiables.", "groups": [{"position": 1, "keywords": ["pas de promesse vague", "mesures vérifiables", "pratiques"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment impliquez-vous les parents de Nathan dans la suite de cette situation ?", "hint": "L''information des parents doit se faire de manière à soutenir Nathan plutôt qu''à aggraver sa peur ou sa honte.", "perfect": "Je m''assure que les parents de Nathan soient informés de la situation, cette étape étant nécessaire pour organiser une prise en charge complète incluant leur propre vigilance et soutien à son égard.\n\nJe prépare, si possible avec l''aide de l''établissement scolaire, la manière dont cette information leur sera communiquée, en évitant une annonce brutale qui pourrait accentuer le sentiment de honte de Nathan face à ce qui lui est arrivé.\n\nJe reste attentive à ce que Nathan ne se sente pas trahi par cette information donnée à ses parents sans qu''il ait pu s''y préparer, en cherchant si possible à l''associer à la manière dont cette annonce sera faite.\n\nJe recommande aux parents des mesures concrètes qu''ils peuvent eux-mêmes mettre en place, comme accompagner ou faire accompagner Nathan sur le trajet du collège, ce qui répond directement au risque de récidive identifié.", "points": [{"position": 1, "label": "S''assurer que les parents soient informés de la situation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Nécessaire pour une prise en charge complète incluant leur vigilance.", "groups": [{"position": 1, "keywords": ["parents informés", "prise en charge complète", "vigilance parentale"]}]}, {"position": 2, "label": "Préparer une communication évitant une annonce brutale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter d''accentuer le sentiment de honte de Nathan.", "groups": [{"position": 1, "keywords": ["éviter l''annonce brutale", "sentiment de honte", "communication préparée"]}]}, {"position": 3, "label": "Chercher à associer Nathan à la manière dont l''annonce sera faite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter qu''il se sente trahi par une information non préparée.", "groups": [{"position": 1, "keywords": ["associer Nathan", "ne pas se sentir trahi", "préparation"]}]}, {"position": 4, "label": "Recommander des mesures concrètes aux parents pour le trajet", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Répondre directement au risque de récidive identifié.", "groups": [{"position": 1, "keywords": ["mesures concrètes", "accompagner le trajet", "risque de récidive"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('mineurs-degradations-groupe-adolescents', '{"slug": "mineurs-degradations-groupe-adolescents", "title": "Ils sont cinq, aucun ne reconnaît avoir tenu la bombe de peinture", "theme_slug": "mineurs", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 19 heures. Vous êtes engagés à une aire de jeux suite au signalement d''un riverain ayant vu un groupe de cinq adolescents, âgés de 13 à 15 ans, en train de taguer les murs d''un local technique attenant avec de la bombe de peinture. À votre arrivée, les cinq jeunes sont encore sur place, une bombe de peinture vide abandonnée au sol à quelques mètres d''eux, mais aucun ne reconnaît avoir personnellement tenu l''objet ni réalisé les tags constatés sur le mur.\n\nChacun affirme être « juste venu voir » ou avoir « juste regardé », rejetant implicitement la responsabilité sur les autres membres du groupe sans qu''aucun nom ne soit spontanément avancé. Les dégradations elles-mêmes sont visibles et non contestées dans leur existence, seule leur paternité individuelle restant floue.\n\nAucun des cinq ne semble être le meneur évident du groupe, leurs explications se ressemblant toutes dans leur volonté commune de nier une implication personnelle directe.", "questions": [{"position": 1, "max_points": 5, "label": "Comment gérez-vous cette dilution collective de la responsabilité entre les cinq adolescents ?", "hint": "Le fait qu''aucun ne reconnaisse individuellement les faits ne doit pas conduire à renoncer à toute investigation sur les responsabilités.", "perfect": "Je sépare les cinq adolescents avant de recueillir leurs explications individuelles, cette séparation étant essentielle pour éviter que leurs versions ne continuent à se caler les unes sur les autres dans un discours collectif de déni.\n\nJe recueille séparément le récit de chacun sur ce qui s''est passé, en étant attentive aux détails qui pourraient varier d''un jeune à l''autre et révéler des incohérences dans cette version commune de la simple présence passive.\n\nJe ne me satisfais pas d''une conclusion selon laquelle personne ne serait individuellement responsable du seul fait que tous nient avoir agi, cette dilution collective ne devant pas aboutir à une impunité de fait pour des dégradations pourtant bien réelles et visibles.\n\nJe recherche des éléments matériels complémentaires, comme des traces de peinture sur les mains ou les vêtements de l''un ou l''autre des adolescents, qui pourraient objectiver une implication plus directe malgré leurs dénégations verbales communes.", "points": [{"position": 1, "label": "Séparer les cinq adolescents avant de recueillir leurs explications", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : séparer les mineurs et individualiser les responsabilités.", "groups": [{"position": 1, "keywords": ["séparer les adolescents", "éviter le calage des versions", "individualiser"]}]}, {"position": 2, "label": "Recueillir séparément chaque récit en étant attentive aux incohérences", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Détails variables pouvant révéler des incohérences dans le déni commun.", "groups": [{"position": 1, "keywords": ["récits séparés", "incohérences", "déni commun"]}]}, {"position": 3, "label": "Ne pas se satisfaire d''une conclusion d''absence de responsabilité individuelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Dilution collective ne devant pas aboutir à une impunité de fait.", "groups": [{"position": 1, "keywords": ["ne pas se satisfaire", "pas d''impunité", "dilution collective"]}]}, {"position": 4, "label": "Rechercher des éléments matériels complémentaires", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traces de peinture pouvant objectiver une implication directe.", "groups": [{"position": 1, "keywords": ["éléments matériels", "traces de peinture", "objectiver l''implication"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous ces mineurs compte tenu de leur jeune âge et de l''absence de victime physique dans ces faits ?", "hint": "L''absence de victime physique directe ne signifie pas l''absence de préjudice réel à considérer.", "perfect": "Je reste consciente que malgré l''absence de victime physique, ces dégradations causent un préjudice réel, à savoir le coût de remise en état du local technique et l''atteinte à un espace public partagé par la collectivité.\n\nJe traite ces mineurs avec une approche adaptée à leur âge, privilégiant une réponse à la fois ferme sur la reconnaissance des faits et pédagogique sur les conséquences réelles de ce type d''acte, plutôt qu''une réponse uniquement répressive disproportionnée par rapport à la gravité des faits.\n\nJe respecte le cadre protecteur applicable à leur situation de mineurs, notamment concernant l''information de leurs représentants légaux avant toute démarche formelle plus poussée.\n\nJe ne minimise pas pour autant ces faits comme une simple bêtise sans conséquence, en gardant à l''esprit que la répétition de ce type de comportement sans réponse appropriée pourrait encourager une escalade future.", "points": [{"position": 1, "label": "Reconnaître le préjudice réel malgré l''absence de victime physique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Coût de remise en état et atteinte à un espace collectif.", "groups": [{"position": 1, "keywords": ["préjudice réel", "coût de remise en état", "espace collectif"]}]}, {"position": 2, "label": "Privilégier une approche à la fois ferme et pédagogique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Adaptée à leur âge, ni uniquement répressive ni minimisée.", "groups": [{"position": 1, "keywords": ["ferme et pédagogique", "adapté à l''âge", "pas uniquement répressif"]}]}, {"position": 3, "label": "Respecter le cadre protecteur applicable aux mineurs", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information des représentants légaux avant toute démarche poussée.", "groups": [{"position": 1, "keywords": ["cadre protecteur", "représentants légaux", "avant démarche poussée"]}]}, {"position": 4, "label": "Ne pas minimiser comme une simple bêtise sans conséquence", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter d''encourager une escalade future sans réponse appropriée.", "groups": [{"position": 1, "keywords": ["pas une simple bêtise", "escalade future", "réponse appropriée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite avec les parents de ces cinq adolescents ?", "hint": "L''implication des parents doit se faire de manière cohérente pour l''ensemble du groupe, malgré des degrés d''implication individuelle encore flous.", "perfect": "Je m''assure que les parents de chacun des cinq adolescents soient informés de cette intervention, cette information restant nécessaire indépendamment du degré exact de responsabilité individuelle qui reste encore à établir.\n\nJe présente la situation de manière factuelle à chaque famille, sans désigner prématurément un responsable principal parmi les cinq avant que l''enquête n''ait pu clarifier davantage les rôles de chacun.\n\nJe recommande aux familles une réflexion commune sur la fréquentation de ce groupe par leurs enfants respectifs, ce type de dynamique collective pouvant se reproduire si aucune prise de conscience n''intervient à ce stade.\n\nJe reste disponible pour orienter les familles vers des dispositifs de médiation ou d''accompagnement éducatif si cela leur semble utile, sans que cela ne relève strictement de ma seule compétence policière.", "points": [{"position": 1, "label": "S''assurer que les parents de chacun soient informés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Indépendamment du degré exact de responsabilité encore à établir.", "groups": [{"position": 1, "keywords": ["parents informés", "indépendamment du degré", "à établir"]}]}, {"position": 2, "label": "Présenter la situation factuellement sans désigner de responsable prématuré", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Avant que l''enquête ne clarifie davantage les rôles.", "groups": [{"position": 1, "keywords": ["factuellement", "sans désigner prématurément", "rôles à clarifier"]}]}, {"position": 3, "label": "Recommander une réflexion commune sur la fréquentation du groupe", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Dynamique collective pouvant se reproduire sans prise de conscience.", "groups": [{"position": 1, "keywords": ["réflexion sur le groupe", "dynamique collective", "prise de conscience"]}]}, {"position": 4, "label": "Rester disponible pour orienter vers des dispositifs de médiation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sans que cela relève strictement de sa seule compétence.", "groups": [{"position": 1, "keywords": ["dispositifs de médiation", "accompagnement éducatif", "hors seule compétence"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('mineurs-consommation-stupefiants-parc', '{"slug": "mineurs-consommation-stupefiants-parc", "title": "Le plus jeune a treize ans et ne tient pas debout", "theme_slug": "mineurs", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Vous êtes engagés dans un parc public suite à un signalement de riverains concernant un groupe de mineurs en train de consommer des substances dans un espace de jeux. À votre arrivée, vous constatez un groupe de quatre adolescents entre 13 et 16 ans, dont le plus jeune, 13 ans, présente des signes préoccupants : il titube fortement, peine à articuler ses mots, et semble sur le point de perdre connaissance à tout moment.\n\nLes trois autres, plus âgés, sont également sous l''effet manifeste d''une consommation récente mais paraissent en meilleur état général, l''un d''eux tentant de soutenir physiquement le plus jeune pour l''empêcher de tomber. Des restes de substances sont visibles au sol à proximité du groupe.\n\nAucun adulte n''est présent, et vous ne savez pas encore ce que le plus jeune a exactement consommé ni en quelle quantité, ce qui rend l''évaluation de son état d''autant plus préoccupante dans l''urgence.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité absolue face à l''état préoccupant de ce mineur de 13 ans ?", "hint": "Face à un risque vital potentiel, le volet sanitaire doit primer sur toute autre considération, y compris répressive.", "perfect": "Ma priorité absolue est de déclencher sans délai une évaluation médicale pour ce jeune de 13 ans, son état titubant et sa difficulté à articuler constituant des signes qui pourraient annoncer une perte de connaissance imminente, voire une urgence vitale.\n\nJe ne me préoccupe pas dans l''instant de la nature exacte ou de la qualification pénale de ce qui a été consommé, cette question relevant d''un traitement ultérieur qui ne doit en rien retarder l''alerte aux secours médicaux.\n\nJe m''assure qu''il reste en position de sécurité en attendant les secours, en le surveillant attentivement pour détecter toute aggravation de son état, notamment une perte de conscience complète qui nécessiterait des gestes immédiats de ma part.\n\nJe recueille auprès des autres jeunes présents, dans la mesure du possible, des informations sur ce qu''il a consommé et depuis combien de temps, ces éléments pouvant être précieux pour les secours médicaux à leur arrivée.", "points": [{"position": 1, "label": "Déclencher sans délai une évaluation médicale pour le plus jeune", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : faire évaluer médicalement avant toute autre démarche.", "groups": [{"position": 1, "keywords": ["évaluation médicale sans délai", "signes préoccupants", "urgence vitale potentielle"]}]}, {"position": 2, "label": "Ne pas se préoccuper dans l''instant de la qualification pénale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Le volet sanitaire prime, sans retarder l''alerte aux secours.", "groups": [{"position": 1, "keywords": ["pas la qualification pénale d''abord", "volet sanitaire prime", "sans retarder"]}]}, {"position": 3, "label": "Le maintenir en position de sécurité en surveillant son état", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Détecter toute aggravation nécessitant des gestes immédiats.", "groups": [{"position": 1, "keywords": ["position de sécurité", "surveiller l''état", "gestes immédiats"]}]}, {"position": 4, "label": "Recueillir des informations sur la consommation pour les secours", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ce qui a été consommé et depuis combien de temps.", "groups": [{"position": 1, "keywords": ["informations pour les secours", "ce qui a été consommé", "durée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous les trois autres adolescents, également sous l''effet d''une consommation mais en meilleur état apparent ?", "hint": "Leur état moins critique ne dispense pas d''une vigilance sur leur propre santé et leur situation.", "perfect": "Je reste vigilante à leur propre état de santé, même s''il paraît moins préoccupant que celui du plus jeune, une consommation de substances pouvant évoluer de manière imprévisible chez tout mineur présent.\n\nJe reconnais le geste de celui qui a tenté de soutenir physiquement le plus jeune, ce comportement solidaire méritant d''être valorisé plutôt qu''ignoré dans la gestion de cette situation collective.\n\nJe recueille leurs explications sur les circonstances de cette consommation, notamment l''origine des substances et si elles ont été partagées entre eux, ce qui pourrait avoir une importance pour comprendre l''ampleur du problème.\n\nJe m''assure qu''ils soient également pris en charge de manière appropriée, sans les traiter uniquement comme des témoins secondaires de la situation du plus jeune, chacun d''eux nécessitant sa propre attention.", "points": [{"position": 1, "label": "Rester vigilante à leur propre état de santé malgré une apparence moins préoccupante", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Évolution imprévisible possible de la consommation.", "groups": [{"position": 1, "keywords": ["vigilance sur leur santé", "évolution imprévisible", "malgré apparence"]}]}, {"position": 2, "label": "Reconnaître le geste solidaire de celui qui a soutenu le plus jeune", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Comportement méritant d''être valorisé.", "groups": [{"position": 1, "keywords": ["geste solidaire", "valoriser", "soutien physique"]}]}, {"position": 3, "label": "Recueillir leurs explications sur les circonstances de la consommation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Origine des substances et partage éventuel entre eux.", "groups": [{"position": 1, "keywords": ["circonstances de la consommation", "origine des substances", "partage entre eux"]}]}, {"position": 4, "label": "S''assurer que chacun bénéficie d''une attention appropriée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Pas seulement traités comme témoins secondaires.", "groups": [{"position": 1, "keywords": ["attention appropriée", "pas seulement témoins", "chacun considéré"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois l''urgence médicale prise en charge par les secours, comment organisez-vous la suite concernant l''information des familles et la qualification des faits ?", "hint": "Le volet répressif et l''information parentale reprennent leur place une fois l''urgence sanitaire traitée, sans pour autant être négligés.", "perfect": "Je m''assure que les familles de l''ensemble des mineurs, et pas seulement celle du plus jeune ayant nécessité une évacuation médicale, soient informées de cette situation, chacun d''eux ayant consommé des substances ce soir.\n\nJe consigne avec précision les circonstances de cette consommation collective, y compris les éléments recueillis sur l''origine des produits, ce qui pourra alimenter une enquête si un fournisseur ou un contexte plus large de trafic devait être identifié.\n\nJe reste attentive à ne pas traiter cette situation uniquement sous l''angle répressif envers ces mineurs, la question de la source d''approvisionnement de ces substances méritant tout autant d''attention que la consommation elle-même.\n\nJe transmets l''ensemble de ces éléments aux services compétents, en insistant sur la particulière vulnérabilité du plus jeune du groupe, qui pourrait nécessiter un suivi spécifique compte tenu de la gravité de son état ce soir.", "points": [{"position": 1, "label": "S''assurer que toutes les familles soient informées, pas seulement celle du plus jeune", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Chacun des mineurs ayant consommé ce soir.", "groups": [{"position": 1, "keywords": ["toutes les familles", "pas seulement le plus jeune", "chacun concerné"]}]}, {"position": 2, "label": "Consigner précisément les circonstances pour une éventuelle enquête sur la source", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Origine des produits utile si un trafic devait être identifié.", "groups": [{"position": 1, "keywords": ["consigner précisément", "source d''approvisionnement", "enquête possible"]}]}, {"position": 3, "label": "Ne pas traiter uniquement sous l''angle répressif envers les mineurs", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "La source mérite autant d''attention que la consommation elle-même.", "groups": [{"position": 1, "keywords": ["pas uniquement répressif", "source d''attention égale", "consommation et origine"]}]}, {"position": 4, "label": "Transmettre en insistant sur la vulnérabilité particulière du plus jeune", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi spécifique compte tenu de la gravité de son état.", "groups": [{"position": 1, "keywords": ["vulnérabilité particulière", "suivi spécifique", "gravité de l''état"]}]}]}]}'::jsonb);